37: static double vector_norm(unsigned n, const double *vec, const double *w, const double *scale_min, const double *scale_max)
38: {
39:     unsigned i;
40:     double ret = 0;
41:     if (scale_min && scale_max) {
42:         if (w)
43:             for (i = 0; i < n; i++)
44:                 ret += w[i] * fabs(sc(vec[i], scale_min[i], scale_max[i]));
45:         else
46:             for (i = 0; i < n; i++)
47:                 ret += fabs(sc(vec[i], scale_min[i], scale_max[i]));
48:     } else {
49:         if (w)
50:             for (i = 0; i < n; i++)
51:                 ret += w[i] * fabs(vec[i]);
52:         else
53:             for (i = 0; i < n; i++)
54:                 ret += fabs(vec[i]);
55:     }
56:     return ret;
