36: static void
37: swapfunc(char *a, char *b, size_t es)
38: {
39: 	char t;
40: 
41: 	do {
42: 		t = *a;
43: 		*a++ = *b;
44: 		*b++ = t;
45: 	} while (--es > 0);
46: }
