48: #define	vecswap(a, b, n)				\
49: 	if ((n) > 0) swapfunc(a, b, n)
50: 
51: #define	CMP(t, x, y) (cmp((t), (x), (y)))
52: 
53: static char *
54: med3(char *a, char *b, char *c, cmp_t *cmp, void *thunk)
55: {
56: 	return CMP(thunk, a, b) < 0 ?
57: 	       (CMP(thunk, b, c) < 0 ? b : (CMP(thunk, a, c) < 0 ? c : a ))
58: 	      :(CMP(thunk, b, c) > 0 ? b : (CMP(thunk, a, c) < 0 ? a : c ));
59: }
