62: void qsort_r_fallback(void *a, size_t n, size_t es, void *thunk, cmp_t *cmp)
63: {
64: 	char *pa, *pb, *pc, *pd, *pl, *pm, *pn;
65: 	size_t d1, d2;
66: 	int cmp_result;
67: 	int swap_cnt;
68: 
69: loop:
70: 	swap_cnt = 0;
71: 	if (n < 7) {
72: 		for (pm = (char *)a + es; pm < (char *)a + n * es; pm += es)
73: 			for (pl = pm;
74: 			     pl > (char *)a && CMP(thunk, pl - es, pl) > 0;
75: 			     pl -= es)
76: 				swapfunc(pl, pl - es, es);
77: 		return;
78: 	}
79: 	pm = (char *)a + (n / 2) * es;
80: 	if (n > 7) {
81: 		pl = a;
82: 		pn = (char *)a + (n - 1) * es;
83: 		if (n > 40) {
84: 			size_t d = (n / 8) * es;
85: 
86: 			pl = med3(pl, pl + d, pl + 2 * d, cmp, thunk);
87: 			pm = med3(pm - d, pm, pm + d, cmp, thunk);
88: 			pn = med3(pn - 2 * d, pn - d, pn, cmp, thunk);
89: 		}
90: 		pm = med3(pl, pm, pn, cmp, thunk);
